def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    stressed_count = 0
    rich_aggressive = 0
    cheap_yesterday = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                stressed_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid <= 35:
                    cheap_yesterday += 1
                if bid >= 80 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if len(alive) == 0:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= 17
    abundance = supply >= 22
    urgent = (hp <= 3) or (no_water_days >= 2)
    semi_urgent = (hp <= 5) or (no_water_days >= 1)

    if urgent:
        base = 96.0 if scarcity else 82.0
        if highest_prev > 0:
            base = max(base, highest_prev + 4.0)
        if rich_aggressive >= 2:
            base += 10.0
        return float(min(budget, base))

    if abundance and hp >= 6 and no_water_days == 0:
        base = 16.0
        if cheap_yesterday >= 2:
            base = 12.0
        return float(min(budget, base))

    if scarcity:
        base = 58.0
        if highest_prev >= 85:
            base = 44.0 if hp >= 7 else 88.0
        elif highest_prev >= 60:
            base = max(base, highest_prev + 2.0)
        else:
            base = max(base, avg_prev + 6.0)
        if stressed_count >= 2:
            base += 8.0
        if rich_aggressive >= 2:
            base += 6.0
        return float(min(budget, base))

    if semi_urgent:
        base = 63.0
        if highest_prev >= 90:
            base = 52.0 if hp >= 6 else 92.0
        elif highest_prev >= 55:
            base = max(base, highest_prev + 1.5)
        if stressed_count >= 2:
            base += 5.0
        return float(min(budget, base))

    base = 34.0
    if highest_prev >= 95:
        base = 24.0
    elif highest_prev >= 75:
        base = 29.0
    elif highest_prev >= 45:
        base = highest_prev + 1.0
    elif avg_prev > 0:
        base = max(base, avg_prev * 0.75)

    if abundance:
        base -= 6.0
    if day >= 8 and hp >= 6:
        base -= 4.0

    if base < 8.0:
        base = 8.0

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # If we can’t pay, bid 0.
    if my_status['budget'] <= 0:
        return 0.0

    # Alive opponents (for trace reaction)
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # Baseline: conserve budget unless pressure is high.
    # Supply pressure: with higher supply, we can bid less and still likely win.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    # Extract yesterday bids from previous_trace (immediate reaction only)
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', None)
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
        elif isinstance(prev, list) and len(prev) > 0:
            # In case previous_trace is a list of dicts, take last
            last = prev[-1]
            if isinstance(last, dict) and last.get('bid') is not None:
                try:
                    prev_bids.append(float(last['bid']))
                except Exception:
                    pass

    # Determine pressure level from yesterday
    highest_prev_bid = None
    if len(prev_bids) > 0:
        highest_prev_bid = max(prev_bids)

    # If no trace info, use a conservative supply-based bid.
    if highest_prev_bid is None:
        # Bid between 0.35 and 0.6 of DAILY_SALARY depending on supply.
        target = DAILY_SALARY * (0.60 - 0.25 * supply_frac)
        return float(min(my_status['budget'], max(0.0, target)))

    # If yesterday someone bid extremely high, avoid getting trapped by overbidding.
    # Instead, bid slightly below the highest to win when others are less aggressive.
    # Also, if my HP is low, I must secure water.
    my_hp = float(my_status['hp'])

    # Aggression thresholds from observed meta-round: ~90-100 were common.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.95
    moderate_pressure = (highest_prev_bid >= DAILY_SALARY * 0.75) and (highest_prev_bid < DAILY_SALARY * 0.95)

    if my_hp <= 2.0:
        # Emergency: bid close to salary.
        base = DAILY_SALARY * (0.85 - 0.10 * supply_frac)
    elif high_pressure:
        base = DAILY_SALARY * (0.65 - 0.15 * supply_frac)
    elif moderate_pressure:
        base = DAILY_SALARY * (0.55 - 0.10 * supply_frac)
    else:
        base = DAILY_SALARY * (0.45 - 0.05 * supply_frac)

    # Undercut strategy: aim just below the highest previous bid.
    # Slightly larger undercut when my HP is healthy to save budget.
    undercut = 2.0
    if my_hp >= 8.0:
        undercut = 4.0
    elif my_hp >= 5.0:
        undercut = 3.0

    target = min(base, highest_prev_bid - undercut)

    # Ensure we’re not bidding too tiny when supply is low.
    # Low supply means water is scarce; increase floor.
    low_supply_floor = DAILY_SALARY * (0.40 + 0.15 * (1.0 - supply_frac))
    if target < low_supply_floor:
        target = low_supply_floor

    # Final cap by budget.
    if target > my_status['budget']:
        target = my_status['budget']

    # Never negative.
    if target < 0.0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_players = len(alive_opponents) + 1

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    total_water_needed_by_all_players = num_alive_players * WATER_REQ
    current_bid = DAILY_SALARY * 0.5

    if day_context['supply'] < total_water_needed_by_all_players:
        if highest_prev_bid > 0:
            current_bid = max(current_bid, highest_prev_bid + (DAILY_SALARY * 0.05))
            if day_context['supply'] < total_water_needed_by_all_players * 0.7:
                 current_bid = max(current_bid, highest_prev_bid + (DAILY_SALARY * 0.1))
        else:
            current_bid = max(current_bid, DAILY_SALARY * 0.7)
    else:
        if my_status['hp'] > 5 and highest_prev_bid < DAILY_SALARY * 0.6:
            current_bid = DAILY_SALARY * 0.4
        elif highest_prev_bid > 0:
            current_bid = max(current_bid, highest_prev_bid * 0.9)
        else:
            current_bid = DAILY_SALARY * 0.45

    if highest_prev_bid > DAILY_SALARY * 0.8 and my_status['hp'] <= 5:
        current_bid = max(current_bid, highest_prev_bid + (DAILY_SALARY * 0.05))

    if day_context['day'] >= EPISODE_DAYS - 2 and my_status['hp'] <= 3:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)

    final_bid = min(my_status['budget'], current_bid)
    final_bid = max(final_bid, DAILY_SALARY * 0.2)

    return final_bid
